import itertools

def simulate_all(N, n):
    count_stay = 0
    for sigma in itertools.permutations(range(N)):
        guests_tags = {i: sigma[i] for i in range(N)}
        for round in range(1, n + 1):
            exiting = [i for i in guests_tags if guests_tags[i] == i]
            for i in exiting:
                del guests_tags[i]

            if not guests_tags:
                break

            remaining_guests = sorted(guests_tags.keys())
            if len(remaining_guests) > 1:
                new_tags = {}
                for i in range(len(remaining_guests)):
                    current_guest = remaining_guests[i]
                    next_guest = remaining_guests[(i + 1) % len(remaining_guests)]
                    new_tags[next_guest] = guests_tags[current_guest]
                guests_tags = new_tags
            else:
                # If only one guest is left, they pass the tag to themselves.
                # The rule is "to the guest sitting immediately to their right".
                # In a circle of one, the guest is their own right neighbor.
                # Let's keep it as is.
                pass 

        if guests_tags:
            count_stay += 1
    return count_stay

for N in range(1, 7):
    for n in range(1, 5):
        print(f"N={N}, n={n}, count={simulate_all(N, n)}")

